import React from 'react';
import './Payments.css';

function Payments() {
  return (
    <div className="Payments">
      <h2>결제 관리</h2>
      <p>관리자를 위한 다양한 데이터를 시각화하여 표시합니다.</p>
      {/* 이곳에 그래프, 통계, 데이터 테이블 등을 추가 */}
    </div>
  );
}

export default Payments;
